def can_jump(nums):
    reach = 0
    for i, step in enumerate(nums):
        if i > reach:
            return False
        reach = max(reach, i + step)
    return True

def subsets(nums):
    res = []
    def go(start, cur):
        res.append(cur[:])
        for i in range(start, len(nums)):
            cur.append(nums[i])
            go(i + 1, cur)
            cur.pop()
    go(0, [])
    return res

def combination_sum(cands, target):
    cands = sorted(cands)
    res = []
    def go(start, remaining, cur):
        if remaining == 0:
            res.append(cur[:]); return
        for i in range(start, len(cands)):
            if cands[i] > remaining: break
            cur.append(cands[i]); go(i, remaining - cands[i], cur); cur.pop()
    go(0, target, [])
    return res

def exist(board, word):
    R, C = len(board), len(board[0])
    def dfs(r, c, i):
        if i == len(word):
            return True
        if r < 0 or c < 0 or r >= R or c >= C or board[r][c] != word[i]:
            return False
        ch, board[r][c] = board[r][c], "#"
        found = (dfs(r + 1, c, i + 1) or dfs(r - 1, c, i + 1) or
                 dfs(r, c + 1, i + 1) or dfs(r, c - 1, i + 1))
        board[r][c] = ch
        return found
    return any(dfs(r, c, 0) for r in range(R) for c in range(C))
